-- LeetTrack question bank ONLY (200 questions, ids 101-300).
--
-- Safe for a live, multi-user database: it never deletes anything and never
-- touches users or solved_questions. Re-running it only inserts missing
-- questions or refreshes their title/topic/url. It has no "USE" line, so run it
-- against whichever database you selected (works with provider-created names).
--
-- Use this (not seed.sql) for the public beta.

AS new_row
ON DUPLICATE KEY UPDATE title = new_row.title, difficulty = new_row.difficulty,
    topic = new_row.topic, url = new_row.url;
